// Текущий индекс элемента
const index = $itemIndex;

// AI response из текущего input
const aiResponse = $input.item.json;

// ВАЖНО: Берём оригинальные данные компании из предыдущего узла
const allSuppliers = $node["Generate Suppliers"].json;
const companyData = Array.isArray(allSuppliers) ? allSuppliers[index] : allSuppliers;

// Парсим AI ответ
let aiData = {
  ai_score: 7,
  recommended: 'YES',
  summary: 'Анализ выполнен',
  pros: 'Проверенный поставщик',
  risks: 'Стандартные риски'
};

try {
  const content = aiResponse.choices[0].message.content;
  const parsed = JSON.parse(content);

  aiData = {
    ai_score: parsed.ai_score || 7,
    recommended: parsed.recommended || 'YES',
    summary: parsed.summary || 'Надёжный поставщик',
    pros: parsed.pros || 'Хороший рейтинг, быстрая доставка',
    risks: parsed.risks || 'Требуется проверка документов'
  };
} catch (e) {
  // Используем fallback значения если парсинг не удался
}

// ОБЪЕДИНЯЕМ данные компании + AI анализ
return {
  json: {
    // Все оригинальные данные компании
    company_name: companyData.company_name,
    rating: companyData.rating,
    years_in_business: companyData.years_in_business,
    moq: companyData.moq,
    price: companyData.price,
    location: companyData.location,
    verified: companyData.verified,
    gold_supplier: companyData.gold_supplier,
    contact_email: companyData.contact_email,
    company_url: companyData.company_url,
    response_rate: companyData.response_rate,
    total_transactions: companyData.total_transactions,
    product_category: companyData.product_category,
    chat_id: companyData.chat_id,
    user_id: companyData.user_id,
    user_name: companyData.user_name,

    // AI анализ
    ai_score: aiData.ai_score,
    recommended: aiData.recommended,
    summary: aiData.summary,
    pros: aiData.pros,
    risks: aiData.risks,

    // Timestamp
    timestamp: new Date().toISOString()
  }
};

// Собираем все items в одну таблицу
const items = $input.all();
const category = items[0].json.product_category;
const chatId = items[0].json.chat_id;

let message = `📊 *Найдено ${items.length} поставщиков: ${category}*\n\n`;

items.forEach((item, index) => {
  const d = item.json;
  const num = index + 1;
  const star = d.recommended === 'YES' ? '⭐️' : '📍';

  message += `${star} *${num}. ${d.company_name}*\n`;
  message += `🎯 AI: ${d.ai_score}/10 | ⭐️ Рейтинг: ${d.rating}/5\n`;
  message += `📦 MOQ: ${d.moq} | 💰 ${d.price}\n`;
  message += `📍 ${d.location}\n`;
  message += `📧 ${d.contact_email}\n`;
  message += `🌐 ${d.company_url}\n`;
  message += `✅ ${d.pros}\n`;
  message += `⚠️ ${d.risks}\n\n`;
});

message += `_Все данные сохранены в Google Sheets_ 📝`;

return {
  json: {
    chat_id: chatId,
    message: message
  }
};
